#!/bin/sh
set -eu
cd "$HOME/code/airk"
"$PWD/artifacts/tools/neo-python-3.13.18/bin/python3.13" -I -B - <<'PY'
import base64,hashlib,json,stat,subprocess
from pathlib import Path
root=Path.cwd().resolve()
names=json.loads(base64.b64decode(''))
files={}
for name in names:
 p=root/name
 assert p.is_relative_to(root) and not p.is_symlink()
 if p.exists():
  assert p.is_file()
  info=p.stat();files[name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':info.st_size,'mode':stat.S_IMODE(info.st_mode)}
 else:files[name]=None
assets={}
for p in (root/'crates/airk-cli/admin-assets').iterdir():
 assert p.is_file() and not p.is_symlink()
 assets[p.relative_to(root).as_posix()]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'mode':stat.S_IMODE(p.stat().st_mode)}
active=[Path(p.strip()).name for p in subprocess.check_output(['/bin/ps','-axo','comm='],text=True).splitlines() if Path(p.strip()).name in ('cargo','cargo-nextest','rustc','clippy-driver','rustfmt')]
print(json.dumps({'files':files,'admin_asset_roster':assets,'active_compilers':active,'read_only':True}))
PY
